import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import catalog from "../generated/catalog.json" with { type: "json" };

// The catalog is generated by `npm run generate:catalog` from the Rust story
// registry, and the invariants about each component — that its type exists,
// that its snippet constructs it, that its events match the source — are Rust
// tests in crates/gallery/src/story.rs. What is left to check here is that the
// committed file still describes the stories the gallery actually ships, which
// catches a stale export without needing a cargo build.
const { components, categories } = catalog;
const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

test("the generated catalog lists every stable Rust story exactly once, in order", async () => {
  const storySource = await readFile(
    path.join(repositoryRoot, "crates/gallery/src/story.rs"),
    "utf8",
  );

  const order = storySource
    .slice(storySource.indexOf("pub const ALL:"))
    .split("];")[0]
    .matchAll(/Self::(\w+),/g);
  const variants = [...order].map((match) => match[1]);

  const slugForVariant = new Map(
    [...storySource.matchAll(/Self::(\w+) => "([a-z0-9-]+)"/g)].map((match) => [
      match[1],
      match[2],
    ]),
  );
  const expected = variants.map((variant) => slugForVariant.get(variant));

  assert.deepEqual(
    components.map(({ slug }) => slug),
    expected,
    "site/generated/catalog.json is stale — run npm run generate:catalog",
  );
});

test("every catalog entry carries what the site renders", async () => {
  const seen = new Set();
  for (const component of components) {
    assert.equal(Number.isInteger(component.sequence), true, `${component.slug} has no sequence`);
    assert.ok(!seen.has(component.slug), `${component.slug} appears twice`);
    seen.add(component.slug);

    assert.match(component.title, /\S/);
    assert.match(component.compactLabel, /\S/);
    assert.match(component.summary, /\S.*\S/);
    assert.match(component.category, /\S/);
    assert.ok(categories.includes(component.category), `${component.category} is not grouped`);
    assert.match(component.viewport, /^(tall|wide)$/);
    assert.match(component.source, /^crates\/gpui-ai\/src\/[a-z_]+\.rs$/);
    assert.match(component.usage, new RegExp(`${component.api}::new`));
    assert.match(component.windowTitle, /gpui-ai$/);
    assert.match(component.limitation, /\S.*\S/);

    for (const key of ["ownership", "interaction", "semantics", "overflow"]) {
      assert.match(component.behavior[key], /\S.*\S/, `${component.slug} has no ${key} note`);
    }

    assert.ok(Array.isArray(component.events));
    assert.equal(component.event, component.events[0] ?? null);
    assert.equal(
      /typed .*Event contracts? and stable application IDs/.test(component.behavior.interaction),
      component.events.length > 0,
      component.slug,
    );

    for (const variant of component.variants) {
      assert.match(variant.id, /^[a-z0-9][a-z0-9-]*$/);
      assert.match(variant.label, /\S/);
    }
  }
});

test("the stories with a switcher report their variants", () => {
  const bySlug = (slug) => components.find((component) => component.slug === slug);

  assert.deepEqual(
    bySlug("chat").variants.map(({ id }) => id),
    ["conversation", "welcome"],
  );
  for (const slug of ["records-table", "diff-table", "filter-table", "comparison-table"]) {
    assert.ok(bySlug(slug).variants.length > 1, `${slug} should offer table states`);
  }
  assert.deepEqual(bySlug("loading").variants, []);
});
